<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserGrantedClientScopes\Infrastructure\Driver;

use Override;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Features\Access\UserGrantedClientScopes\Infrastructure\Driven\UserGrantedClientScopesReadRepositoryAdapter;
use Civi\Lughauth\Features\Access\UserGrantedClientScopes\Infrastructure\Driven\UserGrantedClientScopesWriteRepositoryAdapter;
use Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\Gateway\UserGrantedClientScopesReadGateway;
use Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\Gateway\UserGrantedClientScopesWriteGateway;

class UserGrantedClientScopesPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[UserGrantedClientScopesReadGateway::class] = \DI\autowire(UserGrantedClientScopesReadRepositoryAdapter::class);
        $def[UserGrantedClientScopesWriteGateway::class] = \DI\autowire(UserGrantedClientScopesWriteRepositoryAdapter::class);
        return $def;
    }
}
